"""Degree structure of central graphs C(G).

Verifies that in C(G) every subdivision vertex has degree 2 and every original
vertex has degree n-1, where n = |V(G)|.
"""
from __future__ import annotations
from itertools import combinations
from typing import Iterable, List, Set, FrozenSet, Tuple

def central_graph(vertices: List[int], edges: Set[FrozenSet[int]]):
    cverts = [("o", v) for v in vertices] + [("s", e) for e in edges]
    cedges: Set[FrozenSet] = set()
    for u, w in combinations(vertices, 2):
        if frozenset({u, w}) not in edges:
            cedges.add(frozenset({("o", u), ("o", w)}))
    for e in edges:
        for u in e:
            cedges.add(frozenset({("o", u), ("s", e)}))
    return cverts, cedges

def deg(cedges, v) -> int:
    return sum(1 for e in cedges if v in e)

def cycle(n): return list(range(n)), {frozenset({i,(i+1)%n}) for i in range(n)}

for name, (V, E) in [("C_5", cycle(5)), ("C_7", cycle(7))]:
    cv, ce = central_graph(V, E)
    n = len(V)
    print(name, "n =", n)
    print("  original degrees:", {deg(ce, ("o", v)) for v in V}, "expected", n-1)
    print("  subdivision degrees:", {deg(ce, ("s", e)) for e in E}, "expected 2")

"""Exact AVD-total chromatic number of C(K_3) by backtracking.

C(K_3) is the 6-cycle; the computation returns 4 = n+1, confirming the unified
conjecture on this small instance.
"""
from __future__ import annotations
from itertools import combinations
from typing import Dict, List, Set, FrozenSet, Optional, Tuple

def total_graph(verts, edges):
    tv = [("V", v) for v in verts] + [("E", e) for e in edges]
    adj: Dict = {x: set() for x in tv}
    def link(a, b): adj[a].add(b); adj[b].add(a)
    el = list(edges)
    for e in el:
        u, w = tuple(e); link(("V", u), ("V", w))
    for e in el:
        for u in e: link(("V", u), ("E", e))
    for e, f in combinations(el, 2):
        if e & f: link(("E", e), ("E", f))
    return tv, adj

def colorset(col, edges, v):
    s = {col[("V", v)]}
    for e in edges:
        if v in e: s.add(col[("E", e)])
    return frozenset(s)

def avd_chromatic(verts, edges, hi=10):
    tv, adj = total_graph(verts, edges)
    order = sorted(tv, key=lambda x: -len(adj[x]))
    for k in range(1, hi + 1):
        col: Dict = {}
        def ok(x, c): return all(col.get(nb) != c for nb in adj[x])
        def avd():
            for e in edges:
                u, w = tuple(e)
                if colorset(col, edges, u) == colorset(col, edges, w): return False
            return True
        def bt(i):
            if i == len(order): return avd()
            x = order[i]; used = max(col.values(), default=-1)
            for c in range(min(k, used + 2)):
                if ok(x, c):
                    col[x] = c
                    if bt(i + 1): return True
                    del col[x]
            return False
        if bt(0): return k
    raise RuntimeError("not found")

# C(K_3) = 6-cycle on {a0,a1,a2,s01,s12,s02}
V = ["o0", "o1", "o2", "s01", "s12", "s02"]
E = {frozenset({"o0","s01"}), frozenset({"o1","s01"}),
     frozenset({"o1","s12"}), frozenset({"o2","s12"}),
     frozenset({"o0","s02"}), frozenset({"o2","s02"})}
print("chi''_a(C(K_3)) =", avd_chromatic(V, E), "(expected 4 = n+1)")

